   '2026-06-16T09:00:00.000Z'::timestamptz, '2026-08-13T09:00:00.000Z'::timestamptz),
  ('b1000000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000003', 'ar', 'ربط-واتساب-بفلوفو', 'ربط واتساب بفلوفو', 'اربط رقم واتساب للأعمال (WhatsApp Business) بمساحة عملك واستقبل الرسائل في صندوق الوارد.',
   '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"يعمل فلوفو عبر واجهة واتساب للأعمال الرسمية (WhatsApp Business Platform). هذا يعني أن رقمك يبقى ملكك، ويمكن لأكثر من عضو في الفريق الرد منه في الوقت نفسه."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"قبل أن تبدأ"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"حساب على "},{"type":"text","text":"Meta Business","marks":[{"type":"link","attrs":{"href":"https://business.facebook.com"}}]},{"type":"text","text":" لديك فيه صلاحية مدير."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"رقم هاتف يستطيع استقبال رسالة نصية أو مكالمة للتحقق."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"الرقم غير مستخدم حاليًا في تطبيق واتساب أو واتساب للأعمال على الهاتف. إن كان مستخدمًا، احذف الحساب من التطبيق أولًا."}]}]}]},{"type":"callout","attrs":{"variant":"warning"},"content":[{"type":"paragraph","content":[{"type":"text","text":"حذف حساب واتساب من الهاتف يمسح سجل المحادثات القديم من الجهاز. صدّر المحادثات المهمة قبل ذلك."}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"خطوات الربط"}]},{"type":"steps","content":[{"type":"step","content":[{"type":"paragraph","content":[{"type":"text","text":"من "},{"type":"text","text":"الإعدادات ← القنوات","marks":[{"type":"bold"}]},{"type":"text","text":" اضغط "},{"type":"text","text":"ربط واتساب","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"step","content":[{"type":"paragraph","content":[{"type":"text","text":"سجّل دخولك إلى حساب Meta واختر حساب الأعمال الذي تريد استخدامه."}]}]},{"type":"step","content":[{"type":"paragraph","content":[{"type":"text","text":"أدخل رقم الهاتف بصيغته الدولية، مثل "},{"type":"text","text":"+966 5X XXX XXXX","marks":[{"type":"ltr"}]},{"type":"text","text":"، واختر طريقة التحقق."}]}]},{"type":"step","content":[{"type":"paragraph","content":[{"type":"text","text":"أدخل رمز التحقق المكوّن من ستة أرقام."}]}]},{"type":"step","content":[{"type":"paragraph","content":[{"type":"text","text":"اكتب اسم العرض الذي سيراه العملاء. يجب أن يطابق اسم نشاطك التجاري."}]}]}]},{"type":"figure","attrs":{"src":"/help/whatsapp-connect.svg","alt":"نافذة ربط واتساب تعرض قائمة حسابات الأعمال وحقل رقم الهاتف.","caption":"اختيار حساب الأعمال وإدخال الرقم خلال الربط.","width":1200,"height":720}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"بعد الربط"}]},{"type":"paragraph","content":[{"type":"text","text":"تصل الرسائل الجديدة إلى صندوق الوارد خلال دقائق. أرسل رسالة اختبار من هاتفك إلى الرقم لتتأكد من أن كل شيء يعمل، ثم رُدّ عليها من فلوفو."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"أسئلة شائعة"}]},{"type":"faq","content":[{"type":"faqItem","attrs":{"question":"هل يمكن ربط أكثر من رقم؟"},"content":[{"type":"paragraph","content":[{"type":"text","text":"نعم. كل رقم يظهر كقناة مستقلة في صندوق الوارد، ويمكنك تحديد الفريق المسؤول عن كل رقم."}]}]},{"type":"faqItem","attrs":{"question":"هل أفقد المحادثات القديمة؟"},"content":[{"type":"paragraph","content":[{"type":"text","text":"المحادثات التي جرت عبر تطبيق الهاتف لا تنتقل إلى فلوفو. تبدأ الرسائل بالظهور من لحظة الربط."}]}]},{"type":"faqItem","attrs":{"question":"ماذا لو لم يصلني رمز التحقق؟"},"content":[{"type":"paragraph","content":[{"type":"text","text":"انتظر دقيقتين ثم اطلب الرمز عبر مكالمة بدل الرسالة النصية. إن استمر التعذّر، تأكد من أن الرقم غير مسجّل في تطبيق آخر."}]}]}]}]}'::jsonb,
   'يعمل فلوفو عبر واجهة واتساب للأعمال الرسمية (WhatsApp Business Platform). هذا يعني أن رقمك يبقى ملكك، ويمكن لأكثر من عضو في الفريق الرد منه في الوقت نفسه.

قبل أن تبدأ

- حساب على Meta Business لديك فيه صلاحية مدير.
- رقم هاتف يستطيع استقبال رسالة نصية أو مكالمة للتحقق.
- الرقم غير مستخدم حاليًا في تطبيق واتساب أو واتساب للأعمال على الهاتف. إن كان مستخدمًا، احذف الحساب من التطبيق أولًا.

حذف حساب واتساب من الهاتف يمسح سجل المحادثات القديم من الجهاز. صدّر المحادثات المهمة قبل ذلك.

خطوات الربط

1. من الإعدادات ← القنوات اضغط ربط واتساب.
2. سجّل دخولك إلى حساب Meta واختر حساب الأعمال الذي تريد استخدامه.
3. أدخل رقم الهاتف بصيغته الدولية، مثل +966 5X XXX XXXX، واختر طريقة التحقق.
4. أدخل رمز التحقق المكوّن من ستة أرقام.
5. اكتب اسم العرض الذي سيراه العملاء. يجب أن يطابق اسم نشاطك التجاري.

اختيار حساب الأعمال وإدخال الرقم خلال الربط.

بعد الربط

تصل الرسائل الجديدة إلى صندوق الوارد خلال دقائق. أرسل رسالة اختبار من هاتفك إلى الرقم لتتأكد من أن كل شيء يعمل، ثم رُدّ عليها من فلوفو.

أسئلة شائعة

هل يمكن ربط أكثر من رقم؟
نعم. كل رقم يظهر كقناة مستقلة في صندوق الوارد، ويمكنك تحديد الفريق المسؤول عن كل رقم.

هل أفقد المحادثات القديمة؟
المحادثات التي جرت عبر تطبيق الهاتف لا تنتقل إلى فلوفو. تبدأ الرسائل بالظهور من لحظة الربط.

ماذا لو لم يصلني رمز التحقق؟
انتظر دقيقتين ثم اطلب الرمز عبر مكالمة بدل الرسالة النصية. إن استمر التعذّر، تأكد من أن الرقم غير مسجّل في تطبيق آخر.',
   null, null, null, '[{"id":"قبل-أن-تبدأ","level":2,"text":"قبل أن تبدأ"},{"id":"خطوات-الربط","level":2,"text":"خطوات الربط"},{"id":"بعد-الربط","level":2,"text":"بعد الربط"},{"id":"أسئلة-شائعة","level":2,"text":"أسئلة شائعة"}]'::jsonb, 1,
