   '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Flovoo plans are priced per team seat per month, plus the WhatsApp conversation fees that Meta charges, passed through on your invoice without mark-up."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Compare plans"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":""}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Starter"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Professional"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Business"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Channels"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"WhatsApp plus one more"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"All channels"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"All channels"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Seats"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Up to 3"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Up to 15"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Unlimited"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Automation"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Auto-replies"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Auto-